package android.net; public final class Uri {private final String value; private Uri(String v){value=v;} public static Uri parse(String s){return new Uri(s);} public String getScheme(){return value.substring(0,value.indexOf(':'));} public boolean equals(Object o){return o instanceof Uri && value.equals(((Uri)o).value);} public int hashCode(){return value.hashCode();} public String toString(){return value;}}
